    "text": "La meva àvia es diu Rosa i té setanta anys. És baixeta i una mica grassoneta. Té els cabells blancs i curts, i sempre porta unes ulleres vermelles penjades d'un cordó. Els seus ulls són petits i blaus, i quan riu se li fan arrugues a les galtes.\nL'àvia Rosa és molt riallera i pacient. Mai no s'enfada quan li faig mil preguntes. Li agrada molt fer mitja i cuidar les tomaqueres del seu hort, a prop del riu Gurri. Cada dissabte em ve a buscar i anem juntes al mercat de Vic. Allà saluda tothom, perquè coneix mig Vic!\nQuan sigui gran, m'agradaria ser tan alegre com ella.",
