    "titol": "El nou company",
    "tema": "Descripció de persones",
    "text": "Avui ha arribat un nen nou a la classe de tercer. Es diu Arnau i ve de Manlleu. És molt alt, el més alt de tots, i té els cabells arrissats i de color castany. Té la cara plena de pigues i, quan somriu, se li veu el forat d'una dent que li ha caigut.\nAl principi estava callat i mirava a terra, però a l'hora del pati li hem preguntat si volia jugar a futbol. Ha dit que sí i ha marcat dos gols! Després ens ha explicat que li encanten els animals i que té una tortuga que es diu Bala.\n—Bala? Si les tortugues són molt lentes! —ha dit la Laia.\n—Per això mateix! —ha respost l'Arnau, rient.\nCrec que serem bons amics.",
