    "text": "La girafa és l'animal més alt del món. Viu a les sabanes d'Àfrica, unes planes grans amb herba i pocs arbres. Un mascle adult pot fer més de cinc metres d'alçada, gairebé com una casa de dos pisos.\nGràcies al seu coll tan llarg, la girafa arriba a les fulles més altes de les acàcies, que són el seu menjar preferit. Per agafar-les fa servir la llengua, que és de color fosc i mesura gairebé mig metre.\nLa girafa dorm molt poc: menys de dues hores al dia, i sovint dreta. Quan vol beure, ha d'obrir molt les potes del davant i abaixar el cap fins a terra. En aquesta posició no pot vigilar bé, i els lleons la poden atacar.",
