    "titol": "La Lluna ha tornat",
    "tema": "Animals de companyia (narració)",
    "text": "En Marc té una gossa que es diu Lluna. És petita, de pèl negre, i té una taca blanca al front en forma de mitja lluna. Per això li van posar aquest nom.\nUn diumenge, mentre passejaven pel bosc, la Lluna va sentir un conill i va sortir corrent darrere seu. En Marc la va cridar molt fort, però la gossa no va tornar.\nLa van buscar tota la tarda amb els pares. Quan es va fer fosc, van tornar a casa molt tristos.\nL'endemà al matí, el nen va sentir uns gemecs a la porta. Va obrir i... allà hi havia la Lluna, plena de fang i remenant la cua!\n—On has estat, entremaliada? —va dir en Marc, abraçant-la.\nDes d'aquell dia, quan van al bosc, en Marc no li treu mai la corretja.",
