    "text": "Saps que les papallones no neixen amb ales? Al llarg de la seva vida, passen per quatre fases. Aquest canvi tan gran s'anomena metamorfosi.\n1. L'ou. La papallona femella pon els ous a sota d'una fulla. Són petits com un cap d'agulla.\n2. L'eruga. De cada ou en surt una eruga, que només fa una cosa: menjar fulles i més fulles! Creix tant que ha de canviar de pell unes quantes vegades.\n3. La crisàlide. Quan ja és grossa, l'eruga s'embolica dins d'una closca dura i s'hi queda quieta uns quants dies. Per fora sembla que no passi res, però per dins tot el seu cos està canviant.\n4. La papallona. Un dia, la closca s'obre i en surt una papallona. Al principi té les ales arrugades i molles. Les ha d'estendre i deixar assecar abans de poder volar.",
