    "text": "Un dia de molta calor, una formiga tenia set i va baixar al riu a beure. Però va relliscar i va caure a l'aigua. La pobra formiga no podia sortir.\nUn colom que era en un arbre de la vora ho va veure. De seguida va arrencar una fulla amb el bec i la va deixar caure a l'aigua, al costat de la formiga. La formiga s'hi va enfilar i, com si fos una barqueta, va arribar a la riba.\n—Gràcies, colom! Algun dia t'ho tornaré —va dir.\nUns dies després, un caçador va apuntar el colom amb la seva escopeta. La formiga ho va veure i li va picar el peu. El caçador va fer un crit i el colom, en sentir-lo, va fugir volant.\nQui fa un favor, en rep un altre.",
