    "text": "Vic, 14 de novembre. Des d'aquesta setmana, la biblioteca de l'escola obre les portes a l'hora del pati els dimarts i els dijous. La iniciativa ha sorgit del consell d'alumnes, que demanava un espai tranquil per llegir i jugar a jocs de taula.\nCada dia, dos alumnes de cinquè o sisè fan de bibliotecaris voluntaris: registren els préstecs, ordenen els llibres als prestatges i recomanen lectures als més petits. Els llibres es poden endur a casa durant quinze dies.\n—Abans, a l'hora del pati, m'avorria. Ara he descobert els còmics d'aventures i no puc parar de llegir! —explica l'Ona, de quart.\nLa direcció ha anunciat que, si l'experiència funciona, la biblioteca també obrirà els divendres.",
