    "titol": "Carta des de la Cantània",
    "tema": "La Cantània i la música coral (carta)",
    "text": "Vic, 3 de juny\nEstimada tieta Marta,\nCom estàs? T'escric per explicar-te una cosa increïble: dissabte passat vam cantar a la Cantània! És un projecte en què nens i nenes de moltes escoles de Catalunya aprenen una mateixa cantata durant tot el curs i després la canten junts en un gran concert.\nVam assajar cada setmana amb la mestra de música. Algunes cançons eren difícils, sobretot una en què havíem de cantar a tres veus. Però el dia del concert, amb l'orquestra i centenars de nens cantant alhora, em va semblar que el cor m'esclatava d'alegria.\nL'any que ve hi tornaré, segur! Ah, i la mare ho va gravar tot: quan vinguis, t'ho ensenyaré.\nUna abraçada molt forta,\nPau",
