    "text": "Mart és el quart planeta del sistema solar, comptant des del Sol. Si el mirem de nit amb un telescopi, el veurem d'un color vermellós. Aquest color es deu a les roques i a la pols del seu terra, que contenen molt de ferro rovellat.\nMart és més petit que la Terra i molt més fred: la temperatura mitjana és d'uns seixanta graus sota zero. No té oceans, però els científics hi han trobat gel als pols.\nEn aquest planeta hi ha l'Olympus Mons, el volcà més gran del sistema solar. És més de dues vegades més alt que l'Everest!\nMart té dues llunes petites, Fobos i Deimos. Avui dia, uns quants robots n'exploren la superfície per esbrinar si algun dia hi va haver vida.",
