    "text": "La Júlia té vuit anys i és l'enxaneta de la colla castellera de la seva ciutat. Avui actuen a la plaça Major de Vic, i tota la família ha vingut a veure-la.\nElla s'ajusta el casc i respira profundament. A sota, centenars de castellers fan pinya, braç amb braç, per aguantar el castell. Comencen a sonar les gralles: és el senyal!\nLa Júlia s'enfila pel tronc: espatlles, faixes, mans que l'ajuden. No mira avall. Quan arriba dalt de tot, aixeca la mà i fa l'aleta. La plaça esclata en aplaudiments.\nDesprés baixa amb compte, perquè un castell no s'acaba fins que no es desmunta sencer. Quan toca a terra, el cap de colla l'abraça:\n—Molt bé, Júlia! Ets molt valenta!",
