    "text": "La Patum és la festa més important de Berga, la capital del Berguedà. Se celebra per Corpus, a finals de maig o al juny. L'any 2005, la UNESCO la va declarar Obra Mestra del Patrimoni Oral i Immaterial de la Humanitat.\nEl nom ve del so del tabal, un gran timbal que fa «pa-tum, pa-tum» pels carrers per anunciar la festa.\nDurant la Patum surten diverses comparses: els Turcs i Cavallets, les Maces, les Guites, l'Àliga, els Nans i els Gegants. Les guites són una mena de dracs que llancen espurnes i persegueixen la gent.\nEl moment més esperat és el salt de Plens: un centenar de plens, diables coberts d'herba amb foc al cap, ballen a la plaça, plena de fum i de música.",
