    "text": "Vic, 17 d'octubre. Aquest matí, tots els alumnes de primària de l'escola han participat en la cursa solidària que se celebra cada tardor. Els de primer i segon han fet una volta al pati; els de tercer i quart, dues voltes al barri; i els de cinquè i sisè, un recorregut de tres quilòmetres.\nAbans de la cursa, cada alumne havia buscat padrins: familiars o veïns que donaven un euro per cada volta o quilòmetre. En total, s'han recaptat 2340 euros, que serviran per construir un pou d'aigua en una escola de Kenya.\n—No he guanyat, però he arribat a la meta i he ajudat molta gent! —deia, suat i content, l'Eloi, de quart.\nL'any vinent, els mestres volen convidar també les famílies a córrer.",
