    "titol": "La guineu i el corb",
    "tema": "Les faules",
    "text": "Un matí, un corb va robar un tros de formatge d'una finestra i se'n va anar a menjar-se'l dalt de la branca d'un pi.\nUna guineu que passava per sota va sentir l'olor del formatge i se'l va mirar amb ulls golafres. Com que no podia enfilar-se a l'arbre, va pensar un truc.\n—Bon dia, senyor corb! Quines plomes tan negres i brillants que té! —va dir amb veu dolça—. Si la seva veu és tan bonica com les seves plomes, segur que és el rei dels ocells del bosc.\nEl corb, molt cofoi, va voler demostrar que cantava bé. Va obrir el bec per cantar ben fort... i el formatge va caure a terra.\nLa guineu el va atrapar d'un salt i, abans de marxar, li va dir:\n—Aprèn la lliçó, amic: no et refiïs mai de qui t'afalaga.",
