    "tema": "El cicle de l'aigua (text científic)",
    "text": "L'aigua de la Terra fa un viatge que es repeteix sense parar, com un cercle. És el cicle de l'aigua.\nTot comença quan el sol escalfa l'aigua dels mars, dels rius i dels llacs. Amb la calor, una part de l'aigua es converteix en vapor, un gas que no veiem, i puja cap amunt. Aquest pas s'anomena evaporació.\nAllà dalt fa fred, i el vapor es refreda i es transforma en gotetes molt petites. Milions de gotetes juntes formen els núvols. És la condensació.\nQuan les gotes dels núvols es fan grosses i pesants, cauen a terra en forma de pluja, o de neu si fa molt fred. És la precipitació.\nAquesta aigua baixa pels rius, s'escola sota terra o torna al mar. I el viatge torna a començar!",
