    "text": "Què necessites?\n- un pot de vidre net\n- cotó fluix\n- tres mongetes seques\n- una mica d'aigua\nQuè has de fer?\n1. Omple el pot de cotó fluix, sense premsar-lo gaire.\n2. Col·loca les mongetes entre el cotó i el vidre, perquè les puguis veure des de fora.\n3. Mulla el cotó amb aigua. Ha de quedar humit, però no ple d'aigua.\n4. Deixa el pot en un lloc amb llum, però on no toqui el sol directe.\n5. Cada dia, comprova que el cotó continuï humit i, si cal, afegeix-hi unes gotes d'aigua.\n6. Apunta en una llibreta els canvis que vegis i dibuixa'ls.\nQuè passarà?\nAl cap d'uns quants dies, la pell de la mongeta s'esquerdarà i en sortirà una arrel blanca que creixerà cap avall. Després apareixerà una tija amb dues fulletes verdes.",
