    "tema": "Oficis: la veterinària (entrevista)",
    "text": "Avui parlem amb la Núria, que treballa en una clínica veterinària de Manlleu.\n—Núria, quins animals cures?\n—Sobretot gossos i gats, però també conills i tortugues. Un cop vaig curar una iguana!\n—Com és un dia normal a la clínica?\n—Al matí faig visites: vacuno els animals, els peso i els escolto el cor. A la tarda, si cal, faig operacions.\n—Què és el més difícil de la teva feina?\n—Que els animals no em poden dir on els fa mal. Els he d'observar molt bé: com caminen, com mengen, si tenen els ulls tristos...\n—Tens animals a casa?\n—Sí, un gos que es diu Tro. El vaig trobar abandonat al costat d'una carretera i ara és el meu millor amic.\n—Quin consell dones a les famílies que volen un animal?\n—Que no és una joguina: cal donar-li menjar, passejar-lo i estimar-lo cada dia, durant molts anys.",
