    "text": "Vic, 9 de juny. Els alumnes de quart han collit aquesta setmana les primeres verdures de l'hort que van plantar a la primavera, en un racó assolellat del pati.\nL'hort té quatre bancals. En el primer hi van sembrar enciams; en el segon, pèsols; en el tercer, maduixes, i en el quart, herbes aromàtiques com el julivert i la menta. Cada dia, un grup d'alumnes s'encarregava de regar i de treure les males herbes.\n—Al principi, les plantes eren tan petites que pensàvem que no creixerien mai! —explica en Hugo.\nAmb la primera collita, els alumnes van preparar una amanida per a tota la classe. Les maduixes, en canvi, no van arribar a l'amanida: els ocells se les havien menjat!\nPer a l'any vinent, els alumnes volen posar-hi un espantaocells.",
