    "titol": "Ombres a la paret",
    "tema": "Les colònies (narració)",
    "text": "Aquell estiu, la Mariona i el seu cosí Roc van anar de colònies a una casa de pagès.\nLa tercera nit, quan tothom dormia, un tro fortíssim els va despertar. Plovia tant que l'aigua repicava a les teules com si fossin timbals. De sobte, es va apagar la llum.\n—Mariona, tens por? —va xiuxiuejar en Roc.\n—Una mica... —va confessar ella.\nLlavors la Mariona va recordar que tenia una llanterna a la motxilla. La va encendre i, amb les mans, va començar a fer ombres a la paret: un conill, un ocell, un gos que bordava...\nEls altres nens de l'habitació es van anar despertant i, en lloc de plorar, reien i endevinaven quins animals eren.\nQuan va arribar el monitor, preocupat, es va trobar tota l'habitació fent un concurs d'ombres.\n—Doncs sembla que aquí ningú no té por de la tempesta! —va dir, rient.",
