    "titol": "El pop, un animal enginyós",
    "tema": "Animals del mar (text expositiu)",
    "text": "El pop és un animal marí que viu al fons del mar, amagat entre les roques. No té ossos, i per això pot ficar-se en forats molt petits.\nTé vuit braços plens de ventoses, que li serveixen per arrossegar-se pel fons, per agafar les preses i per enganxar-se a les roques. Menja crancs, petxines i peixos petits.\nEl pop té tres cors i la sang de color blau. Però el que el fa més especial és la manera com es defensa. Pot canviar el color de la pell en un instant per confondre's amb les roques i la sorra. I, si un enemic l'empaita, llança un núvol de tinta negra i fuig expulsant aigua amb força.\nEls científics diuen que el pop és un dels animals sense ossos més intel·ligents: sap obrir pots i resoldre petits trencaclosques.",
