    "titol": "Els ausetans de l'Esquerda",
    "tema": "Els ibers a Osona",
    "text": "Molt abans que arribessin els romans, a la Plana de Vic hi vivia un poble iber: els ausetans. Els ibers no formaven un sol país, sinó molts pobles diferents repartits per la costa i l'interior de la península. Cada poble tenia el seu territori i els seus poblats.\nUn dels llocs on millor podem conèixer com vivien els ausetans és el jaciment de l'Esquerda, a Roda de Ter. És dalt d'un turó situat en un meandre del riu Ter, un revolt tan tancat que l'aigua l'envolta per tres costats. Era un lloc fàcil de defensar, i per això els ibers hi van construir un poblat protegit amb una muralla.\nEls arqueòlegs hi han trobat restes de cases, sitges per guardar el gra, molins de pedra i trossos de ceràmica. Gràcies a aquestes troballes sabem que els ausetans conreaven cereals, criaven bestiar, teixien la llana i comerciaven amb altres pobles. També parlaven i escrivien la llengua ibèrica: avui sabem llegir els seus signes, però encara no entenem què volen dir.\nSi visiteu el jaciment, imagineu-vos el soroll dels molins, el fum de les llars i els guerrers vigilant des de la muralla. Fa més de dos mil anys, aquell turó estava ple de vida.",
