    "titol": "Guifré el Pelós",
    "tema": "L'edat mitjana a Catalunya",
    "text": "Fa més de mil cent anys, la Plana de Vic era un territori molt poc poblat. Les guerres entre els francs i els musulmans havien fet fugir molts dels seus habitants, i els camps estaven abandonats. Aleshores va aparèixer un personatge clau de la història de Catalunya: el comte Guifré, conegut com el Pelós.\nL'any 878, el rei dels francs li va confiar els comtats de Barcelona i Girona, que se sumaven als d'Urgell i de la Cerdanya, que ja governava. Guifré va decidir repoblar Osona: va animar famílies de les muntanyes a baixar a la plana, on podrien tenir terres per conrear. També va fer construir castells per protegir-les i va restaurar el bisbat de Vic, que va tornar a tenir bisbe l'any 886.\nA més, va fundar el monestir de Santa Maria de Ripoll, on més tard el van enterrar. Els monestirs eren llocs de pregària, però també de treball i de cultura: s'hi copiaven llibres i s'hi ensenyava a llegir.\nGuifré va morir l'any 897 lluitant contra els musulmans. Molts segles després, es va escampar una llegenda que diu que el rei franc va pintar quatre barres a l'escut del comte amb els dits mullats de sang. És només una llegenda, però mostra com el recordaven: com el pare de Catalunya.",
