    "titol": "Diari d'un patge",
    "tema": "La vida en un castell medieval",
    "text": "Em dic Arnau, tinc onze anys i soc patge al castell de Puigsec, a les muntanyes d'Osona. Avui m'he despertat abans que sortís el sol, com cada dia, perquè el cavaller a qui serveixo necessita ajuda per vestir-se. Li he portat aigua per rentar-se i li he lligat les corretges de les botes.\nDesprés he baixat a la cuina, on la Guillema ja encenia el foc. Mentre esmorzava un tros de pa amb formatge, he vist arribar els pagesos del poble carregats amb sacs de blat. Una part de la collita pertany al senyor del castell, i l'han de pujar fins aquí dalt encara que faci fred.\nAl matí he practicat amb l'espasa de fusta al pati. El mestre d'armes diu que soc ràpid, però que encara em falta força. Si treballo de valent, potser d'aquí a uns anys em nomenaran escuder i, algun dia, cavaller.\nA la tarda he ajudat a netejar l'estable i he donat menjar als cavalls. Ara ja és fosc i escric aquestes línies a la llum d'una espelma. Les parets de pedra són fredes, però des de la torre es veu tota la plana coberta de boira. M'agrada viure aquí.",
