    "titol": "La nostra família còsmica",
    "tema": "El sistema solar",
    "text": "El sistema solar és la nostra família còsmica. Al centre hi ha el Sol, una estrella enorme que ens dona llum i calor. Al seu voltant giren vuit planetes, cadascun seguint el seu camí, que anomenem òrbita.\nEls quatre planetes més propers al Sol són Mercuri, Venus, la Terra i Mart. S'anomenen planetes rocosos perquè tenen una superfície sòlida. Mercuri és el més petit i el que es mou més de pressa. Venus és el més calent, perquè té una atmosfera molt espessa que reté la calor com si fos una manta. Mart és conegut com el planeta vermell pel color del seu sòl.\nMés enllà hi ha els gegants: Júpiter, Saturn, Urà i Neptú. Són molt més grans que la Terra i estan formats sobretot per gasos i gel. Júpiter és el més gran de tots: hi cabrien més de mil planetes com el nostre. Saturn és famós pels seus anells, fets de trossos de gel i roca.\nI Plutó? Durant molts anys es va considerar el novè planeta, però l'any 2006 els científics el van classificar com a planeta nan, perquè és petit i comparteix el seu camí amb molts altres cossos.\nLa Terra és l'únic planeta on sabem que hi ha vida. Per això l'hem de cuidar.",
