    "titol": "La vida d'una bassa",
    "tema": "Els ecosistemes",
    "text": "Una bassa pot semblar només un toll gran d'aigua, però si t'hi acostes en silenci descobriràs que és un ecosistema ple de vida. Un ecosistema és el conjunt d'éssers vius que habiten un lloc i les relacions que tenen entre ells i amb el medi: l'aigua, la llum, el sòl i la temperatura.\nA la vora de la bassa hi creixen joncs i canyissos, que serveixen d'amagatall a molts animals. A la superfície hi floten llenties d'aigua i hi patinen els sabaters, uns insectes que sembla que caminin per sobre de l'aigua. A sota, els capgrossos neden entre les algues fins que es transformen en granotes.\nTots aquests éssers estan connectats per cadenes alimentàries. Les algues fabriquen el seu aliment amb la llum del sol; els capgrossos se les mengen; les larves de libèl·lula cacen capgrossos, i el bernat pescaire, amb el seu bec llarg, s'empassa granotes i peixos. Si una de les baules de la cadena desapareix, totes les altres en pateixen les conseqüències.\nPer això és important no llençar-hi deixalles ni deixar-hi anar peixos o tortugues que teníem a casa: poden trencar l'equilibri d'aquest petit món. Una bassa sana és un tresor per a tot l'entorn.",
