    "titol": "Els boscos d'Osona",
    "tema": "Ecosistemes: el bosc",
    "text": "Osona és una comarca de contrastos. Al centre hi ha la plana, plena de camps i pobles, però al seu voltant s'alcen muntanyes cobertes de boscos: el Montseny, les Guilleries o el Collsacabra.\nNo tots aquests boscos són iguals. A les zones més assolellades i seques hi trobem alzinars, amb alzines que mantenen les fulles verdes tot l'any. On fa més fresca i plou més, creixen les rouredes, amb roures que perden la fulla a la tardor. I a les parts altes del Montseny, on la boira és habitual, hi ha fagedes: boscos de faigs que a la tardor es tornen de color de coure.\nEls boscos ens ofereixen molt més que ombra. Les arrels dels arbres subjecten la terra i eviten que la pluja se l'emporti. Les fulles netegen l'aire i fabriquen oxigen. A més, són la casa de senglars, esquirols, guineus, picots i moltes altres espècies.\nPerò els boscos també corren perills. A l'estiu, una burilla o una barbacoa mal apagada poden provocar un incendi que destrueixi en poques hores allò que la natura ha trigat cent anys a fer créixer. Protegir-los és feina de tots.",
