    "titol": "L'invent que va multiplicar els llibres",
    "tema": "Invents: la impremta",
    "text": "Imagina't que, per tenir un llibre, algú l'hagués de copiar a mà, lletra per lletra. Així era fins a mitjan segle XV. A l'edat mitjana, els monjos copistes passaven mesos, i de vegades anys, escrivint un sol volum. Els llibres eren tan cars que gairebé només els tenien els reis, els nobles i l'Església.\nCap a l'any 1450, a la ciutat alemanya de Magúncia, un orfebre anomenat Johannes Gutenberg va tenir una idea brillant. Va fabricar petites peces de metall, cadascuna amb una lletra en relleu. Aquestes peces, anomenades tipus mòbils, es podien combinar per formar paraules i pàgines senceres. Després s'untaven de tinta i es premsaven sobre el paper amb una màquina inspirada en les premses que es feien servir per fer vi.\nL'avantatge era enorme: un cop compostes les pàgines, se'n podien fer centenars de còpies iguals. A més, quan s'acabava un llibre, les lletres es desmuntaven i es reaprofitaven per a un altre. Un dels primers llibres que va imprimir Gutenberg va ser una Bíblia.\nLa impremta es va escampar per Europa a gran velocitat i va arribar a Catalunya unes dues dècades més tard. Els llibres es van abaratir, més persones van aprendre a llegir i les idees van començar a viatjar més de pressa que mai.",
