    "titol": "Alumnes de Vic planten un centenar d'arbres a la vora del Mèder",
    "tema": "La notícia",
    "text": "Vic, 14 de març. Una cinquantena d'alumnes de cinquè d'una escola de Vic van plantar ahir al matí un centenar d'arbres a la riba del riu Mèder, al seu pas per la ciutat. L'activitat formava part d'un projecte per recuperar el bosc de ribera, que en aquest tram havia quedat molt malmès.\nEls nens i nenes, acompanyats de mestres i de tècnics de medi ambient, van plantar àlbers, freixes i salzes, uns arbres que necessiten molta aigua i que creixen bé a prop dels rius. Abans de començar, els tècnics els van ensenyar com fer el forat, com col·locar l'arbre i com trepitjar la terra perquè quedés ben ferma.\n«Les arrels d'aquests arbres subjecten la terra de la riba i eviten que el riu se l'endugui quan baixa ple», va explicar una de les tècniques. A més, el bosc de ribera fa ombra a l'aigua i dona refugi a ocells, amfibis i petits mamífers.\nEls alumnes s'han compromès a tornar-hi cada trimestre per regar els arbres i comprovar com creixen. «Quan siguem grans, hi podrem portar els nostres fills i dir-los que aquests arbres els vam plantar nosaltres», deia, il·lusionada, una de les alumnes.",
