    "titol": "Entrevista a una apicultora",
    "tema": "L'entrevista",
    "text": "La Núria té quaranta ruscos repartits pels camps i boscos de Tona. Fa quinze anys que es dedica a l'apicultura i avui ens explica alguns secrets de les abelles.\n—Núria, com és un rusc per dins?\n—És com una ciutat molt ben organitzada. Hi ha una sola reina, que pon els ous; uns quants centenars de mascles, que s'anomenen abellots, i milers d'obreres, que fan totes les feines: netegen, alimenten les larves, construeixen les cel·les i surten a buscar nèctar.\n—I com fan la mel?\n—Les obreres xuclen el nèctar de les flors i el guarden en un estómac especial. Quan tornen al rusc, el passen a altres obreres, que el dipositen a les cel·les. Després baten les ales per evaporar-ne l'aigua, i així el nèctar es converteix en mel.\n—Les abelles piquen sovint?\n—Només si se senten amenaçades. A més, quan una obrera pica, normalment mor, així que no ho fa per gust.\n—Per què diem que les abelles són tan importants?\n—Perquè, quan van de flor en flor, transporten el pol·len i ajuden les plantes a fer fruits. Sense abelles tindríem moltes menys pomes, cireres o maduixes. Per això cal protegir-les i no fer servir productes tòxics als camps.",
