    "titol": "Carta a l'Ajuntament",
    "tema": "La carta formal",
    "text": "Vic, 3 de febrer\nBenvolgut regidor de Mobilitat:\nSom els alumnes de cinquè d'una escola de Vic i us escrivim per fer-vos una proposta que creiem que milloraria la vida al nostre barri.\nCada dia, molts de nosaltres anem a l'escola a peu o en bicicleta. El problema és que pel carrer que porta a l'entrada hi passen molts cotxes a primera hora, i les voreres són tan estretes que de vegades hem de baixar a la calçada. Alguns pares ens hi porten en cotxe precisament perquè els fa por que hi anem sols.\nPer això us demanem que estudieu la possibilitat de tallar el trànsit d'aquest carrer durant mitja hora a l'entrada i a la sortida de l'escola, tal com ja s'ha fet en altres ciutats. També us proposem que s'hi instal·li un aparcament per a bicicletes.\nCreiem que així hi hauria menys contaminació i menys soroll, i que molts més nens i nenes s'atrevirien a venir caminant o pedalant. Nosaltres ens comprometem a fer una campanya a l'escola per explicar-ho a les famílies.\nUs agraïm per endavant la vostra atenció i quedem a l'espera de la vostra resposta.\nAtentament,\nEls alumnes de 5è",
