    "titol": "Dissabte de mercat",
    "tema": "Narració: el mercat de Vic",
    "text": "Cada dissabte al matí, la Laia acompanya l'avi Pere al mercat de Vic. Per a ella és el millor moment de la setmana. Quan arriben a la plaça Major, que els vigatans anomenen el Mercadal, les parades ja estan muntades i l'aire fa olor de fruita, de formatge i de pa acabat de fer.\n—Primer, la llista —diu l'avi, i treu un paper arrugat de la butxaca.\nLa Laia el llegeix en veu alta: pomes, enciams, ous, un tros de llonganissa i una barra de pa. L'avi té les seves parades preferides i saluda tots els venedors pel nom. A la parada de la Montse compren les pomes i els enciams, que vénen d'un hort de Gurb. Al pagès dels ous, l'avi li pregunta com es troba la seva dona, que havia estat malalta.\n—Avi, per què no comprem al supermercat, que és més ràpid?\nL'avi somriu.\n—Perquè aquí sé d'on ve el que menjo i qui ho ha fet créixer. I perquè, si ningú no hi vingués, el mercat desapareixeria.\nAbans de tornar a casa, s'asseuen en una terrassa sota els porxos. L'avi es pren un cafè i la Laia, una xocolata desfeta. Des d'allà miren com la plaça s'omple de gent, de bosses i de veus. La Laia pensa que, quan sigui gran, també hi vindrà cada dissabte.",
