    "titol": "El viatge d'una gota d'aigua",
    "tema": "Divulgació científica: el cicle de l'aigua",
    "text": "L'aigua que avui beus potser va ploure fa mesos sobre el Montseny, o potser formava part d'un núvol damunt del mar. L'aigua de la Terra no s'acaba ni es crea de nou: es mou sense parar, en un viatge que anomenem cicle de l'aigua.\nTot comença amb el sol. Quan escalfa els mars, els rius i els llacs, una part de l'aigua es converteix en vapor, un gas invisible que puja cap amunt. Aquest pas s'anomena evaporació. Les plantes també deixen anar vapor d'aigua per les fulles.\nA mesura que el vapor s'enlaira, troba aire cada vegada més fred. Llavors es transforma en gotetes molt petites que, totes juntes, formen els núvols. És la condensació.\nQuan les gotetes s'ajunten i pesen massa, cauen en forma de pluja, o de neu i calamarsa si fa molt de fred. Això és la precipitació.\nUna part de l'aigua que cau corre per la superfície fins als rierols i els rius, que la porten cap al mar. Una altra part s'infiltra a terra i forma aigües subterrànies, que de vegades tornen a sortir per una font.\nI, quan arriba al mar, el sol la torna a escalfar... i el viatge torna a començar.",
