    "titol": "En Ton, el rellotger de Vilaclara",
    "tema": "Biografia d'un personatge inventat",
    "text": "Anton Rierola, a qui tothom coneixia com en Ton, va néixer en un mas del Lluçanès un dia de neu de fa molts anys. De petit era un nen callat i curiós, que desmuntava tot el que li queia a les mans: un molinet de cafè, una ràdio vella, el despertador de la seva mare... Ella s'enfadava, però aviat va descobrir que en Ton sempre ho tornava a muntar i que, a més, funcionava millor que abans.\nAls catorze anys va entrar d'aprenent en una rellotgeria de Vic. L'amo, un home sever però just, li va ensenyar a fer servir les pinces, la lupa i uns tornavisos tan prims com agulles. En Ton s'hi passava hores sense badar boca.\nQuan va tenir vint-i-cinc anys, va obrir el seu propi taller a Vilaclara, el seu poble. La seva gran obra va ser arreglar el rellotge del campanar, que feia anys que estava aturat. Hi va dedicar tres mesos de feina, pujant cada dia els cent vint graons de la torre.\nEl dia que el rellotge va tornar a tocar les hores, tot el poble va sortir a la plaça a aplaudir.\nEn Ton va ser el rellotger més estimat de la comarca i va treballar fins que va ser molt gran. Abans de jubilar-se, va ensenyar l'ofici a la seva neta, la Marta, que encara avui té cura del rellotge del campanar.",
