    "titol": "Com venim a l'escola?",
    "tema": "Gràfic descrit en text: una enquesta",
    "text": "Els alumnes de 5è A han fet una enquesta per saber com arriben cada matí a l'escola. Han preguntat als 25 alumnes de la classe i han representat els resultats en un gràfic de barres. Com que aquí no el podeu veure, us l'expliquem amb paraules.\nA l'eix horitzontal hi ha els quatre mitjans de transport: a peu, en cotxe, en bicicleta i en autobús. A l'eix vertical hi ha el nombre d'alumnes.\nLa barra més alta és la d'«a peu»: hi arriben caminant 11 alumnes, gairebé la meitat de la classe. La segona barra és la del cotxe, amb 8 alumnes. Després ve la bicicleta, amb 4 alumnes. Finalment, la barra més baixa és la de l'autobús: només 2 alumnes, que viuen en pobles dels voltants.\nQuan van comentar el gràfic a classe, alguns alumnes que vénen en cotxe van explicar que viuen a prop, però que els pares els hi porten perquè després van a treballar. D'altres van dir que els agradaria venir en bicicleta, però que encara no se senten segurs anant sols pel carrer.\nPer això, la classe ha decidit organitzar una campanya perquè, cada dimecres, les famílies que viuen a prop vinguin caminant. A final de curs repetiran l'enquesta: tenen curiositat per saber si la barra d'«a peu» haurà crescut.",
