    "titol": "Fem un herbari",
    "tema": "Text instructiu: l'herbari",
    "text": "Un herbari és una col·lecció de plantes assecades i ordenades que serveix per conèixer i recordar les espècies d'un lloc. Si vols fer el teu, segueix aquests passos.\nMaterial: un llibre gruixut, paper de diari, cartolines blanques, cinta adhesiva, una lupa i un llapis.\n1. Surt a buscar plantes amb un adult. Agafa només les que siguin abundants, i no arrenquis mai plantes protegides ni plantes de jardins dels altres. N'hi ha prou amb una fulla o una branqueta petita amb flor.\n2. Tria plantes seques: si són molles de pluja o de rosada, es poden florir.\n3. Col·loca cada planta ben estesa entre dos fulls de paper de diari, sense que les fulles quedin plegades.\n4. Posa-ho tot dins del llibre gruixut i, a sobre, uns quants llibres més perquè facin pes.\n5. Canvia el paper de diari cada dos o tres dies, perquè xucli la humitat.\n6. Al cap de dues o tres setmanes, quan la planta estigui ben seca, enganxa-la a una cartolina amb tires de cinta adhesiva.\n7. Escriu-hi a sota una etiqueta amb el nom de la planta, el lloc on l'has trobada i la data.\nConsell: observa les plantes amb la lupa abans d'assecar-les. Descobriràs detalls que a simple vista passen desapercebuts!",
