    "titol": "Cançó del riu",
    "tema": "La poesia: el riu",
    "text": "Neixo petit dalt de la serra,\nun fil d'aigua entre la molsa;\nbaixo saltant de roca en roca\ni canto amb veu clara i dolça.\n\nPasso per sota un pont de pedra\nque ja era vell quan l'avi era nen;\nles truites juguen a amagar-se\nentre les ombres del meu llit lent.\n\nA l'estiu, els nens s'hi banyen\ni em diuen fresc, i em diuen clar;\na la tardor porto fulles grogues\ncom barquetes que van cap al mar.\n\nQuan plou molt, em torno fosc,\nfaig la veu grossa i corro enfadat;\nsurto de mare, inundo els horts,\ni l'endemà ja m'he calmat.\n\nNo em llenceu plàstics ni llaunes,\nque em fan mal i m'apaguen la veu;\ndeixeu-me net, que sense mi\nla terra tindria molta set.\n\nI quan arribo, cansat, al mar,\nli explico tot el que he vist pel camí;\ni el sol m'aixeca cap als núvols\nperquè torni a néixer, petit.",
