    "titol": "L'ingredient secret",
    "tema": "Text teatral",
    "text": "PERSONATGES: L'AVI JOSEP. La NÀDIA, la seva neta.\n(Una cuina. Hi ha una olla al foc. L'AVI JOSEP remena la sopa amb un cullerot. Entra la NÀDIA amb la motxilla a l'esquena.)\nNÀDIA: Avi, ja soc aquí! Què fa tan bona olor?\nAVI JOSEP: Sopa de galets, la teva preferida. Però hi falta l'ingredient secret... i no recordo quin era!\nNÀDIA: (Pensativa.) Potser sal?\nAVI JOSEP: (Tasta la sopa.) No, no. De sal ja en té prou.\nNÀDIA: I pebre?\nAVI JOSEP: Tampoc. L'ingredient secret el posava la teva besàvia, i sempre deia que era el més important de tots.\nNÀDIA: (Obre l'armari i treu un pot.) I això? Diu «Galets».\nAVI JOSEP: (Riu.) No, maca. Els galets ja hi són, a l'olla.\n(La NÀDIA s'asseu a taula, desanimada. L'AVI s'hi asseu al costat i li passa el braç per l'espatlla.)\nAVI JOSEP: Saps què? Ara ho recordo! La besàvia sempre deia: «La sopa, tothom junt a taula». L'ingredient secret no anava a l'olla: era menjar-la en companyia!\nNÀDIA: (Somrient.) Doncs aquest ingredient ja el tenim, avi.\n(L'AVI serveix dos plats. Mengen tots dos, xerrant i rient. Es va fent fosc a l'escenari.)",
