    "titol": "Vine a Vic pel pont!",
    "tema": "El correu electrònic: una carta informal",
    "text": "Assumpte: Vine a Vic pel pont!\nHola, Jana!\nCom estàs? Aquí a Vic ja fa un fred que pela, i cada matí hi ha tanta boira que no veig ni la teulada del veí.\nEt volia preguntar una cosa: per què no véns a passar el pont de desembre a casa nostra? Els teus pares ja hi estan d'acord, només falta que tu diguis que sí.\nHe pensat un pla perfecte. Divendres a la tarda t'esperarem a l'estació de tren. Dissabte al matí anirem en bicicleta fins a la font del bosc, que és un lloc molt bonic, i a la tarda farem galetes amb l'àvia. Diumenge podem anar al cinema o, si plou, fer una marató de jocs de taula. Encara recordo la partida de l'estiu passat, quan em vas guanyar tres vegades seguides!\nPorta roba d'abric, les botes de muntanya i el sac de dormir: dormiràs a la meva habitació, en un matalàs a terra.\nContesta'm aviat, si us plau! I digues-me si encara t'agrada tant la xocolata, que l'àvia et vol preparar una sorpresa.\nUna abraçada molt forta,\nPau\nP.S.: La Pruna, la nostra gata, ha tingut quatre gatets. Ja els veuràs!",
