    "titol": "La garsa i el pit-roig",
    "tema": "Les faules",
    "text": "A l'alzina d'una masia vivia una garsa molt presumida que col·leccionava tot el que brillava: anelles, botons, trossos de vidre i paper d'alumini. Cada matí volava pels voltants a la recerca de tresors nous i els amuntegava al seu niu.\nA la mateixa alzina hi vivia un pit-roig que, durant tota la tardor, recollia llavors i baies i les guardava entre les arrels.\n—Quina pèrdua de temps! —se'n reia la garsa—. Jo tinc el niu més bonic del bosc, i tu només tens grans plens de terra.\nEl pit-roig no li responia i continuava la seva feina.\nVa arribar l'hivern i una gran nevada va cobrir el bosc. No es veia ni una fulla ni una llavor. La garsa, morta de gana, va remenar entre els seus tresors, però ni els botons ni les anelles es podien menjar.\nLlavors va sentir una veueta:\n—Vine, que n'hi ha per a tots dos.\nEra el pit-roig, que li oferia les seves baies. La garsa, avergonyida, va menjar en silenci. Quan va arribar la primavera, va ajudar el pit-roig a recollir llavors i no es va tornar a burlar mai més de ningú.\nMoralitat: allò que brilla no sempre és el que val més, i qui és previsor també pot ser generós.",
