    "titol": "Normes del circuit d'educació viària",
    "tema": "Text instructiu: la pista de bicis",
    "text": "Benvinguts al circuit! Aquest espai reprodueix carrers de veritat, amb semàfors, passos de vianants, rotondes i senyals. Per gaudir-ne amb seguretat, cal complir aquestes normes:\n1. És obligatori portar el casc ben cordat durant tota l'estona que aneu en bicicleta.\n2. Abans de començar, comproveu que els frens funcionen i que les rodes estan ben inflades.\n3. Circuleu sempre per la dreta i en el sentit que indiquen les fletxes pintades a terra.\n4. Respecteu els semàfors i els senyals. Davant d'un senyal de stop, atureu-vos del tot, encara que no vingui ningú.\n5. Quan arribeu a un pas de vianants on hi hagi algú esperant, deixeu-lo passar.\n6. Abans de girar, indiqueu la maniobra estirant el braç cap al costat on voleu anar.\n7. Mantingueu una distància de seguretat amb la bicicleta del davant. No feu curses ni avançaments perillosos.\n8. Els menors de vuit anys han d'anar acompanyats d'una persona adulta.\n9. Si caieu o veieu algú que ha caigut, aviseu de seguida el monitor.\nHorari: de dilluns a divendres, de 17 a 20 h. Dissabtes, d'11 a 14 h.\nRecordeu: el que aprengueu aquí us servirà quan aneu pel carrer. La bicicleta és un vehicle i, com a tal, ha de complir les normes de circulació.",
