    "titol": "El joc de les banderes",
    "tema": "Text instructiu: les normes d'un joc",
    "text": "Jugadors: de 10 a 30, dividits en dos equips.\nMaterial: dues banderes de roba i guix per marcar el terra.\nObjectiu: aconseguir la bandera de l'equip contrari i portar-la fins al teu camp.\nPreparació: dividiu el pati en dos camps iguals amb una línia de guix al mig. Al fons de cada camp, dibuixeu un cercle: és la presó. Al costat de la presó, cada equip hi deixa la seva bandera.\nCom es juga: quan la mestra dona el senyal, els jugadors poden entrar al camp contrari per intentar agafar-ne la bandera. Mentre són al seu camp, ningú no els pot atrapar; però quan travessen la línia del mig, si un rival els toca, han d'anar a la presó de l'altre equip.\nEls presoners poden ser alliberats: si un company arriba a la presó i els toca la mà sense ser atrapat, tots dos tornen caminant al seu camp.\nSi un jugador agafa la bandera i un rival el toca abans d'arribar al seu camp, ha de deixar la bandera on és i anar a la presó.\nQui guanya? L'equip que porta la bandera contrària al seu camp. Si s'acaba el temps i cap equip no ho ha aconseguit, guanya el que tingui més presoners.\nConsell: no ataqueu tots alhora! Cal que alguns jugadors es quedin a defensar.",
