    "titol": "Boira a la Plana",
    "tema": "La poesia",
    "text": "Quan arriba novembre a la Plana,\nla boira s'aixeca de bon matí:\nés un llençol de llana blanca\nque algú ha estès sense dir-ho a ningú.\n\nS'empassa campanars i teulades,\ns'endú els arbres del camí,\ni el sol, com un ou ben pàl·lid,\nno troba la manera de sortir.\n\nVic sembla una ciutat de conte\non tot passa a poc a poc:\nles veus arriben esmorteïdes\ni els fanals fan cercles de foc.\n\nEls nens anem cap a l'escola\namb la bufanda fins al nas;\nsom fantasmes amb motxilla\nque s'esborren a cada pas.\n\nHi ha qui diu que és trista i grisa,\nque fa fred i que fa nosa;\njo hi veig un mar sense onades\non la plana dorm i reposa.\n\nI quan al vespre, per fi,\nla boira se'n va de puntetes,\nel Montseny treu el cap\ni el cel s'omple d'estrelletes.",
