    "tema": "Anuncis i publicitat",
    "text": "Tens set i l'aigua de la teva ampolla està calenta com una sopa? S'ha acabat! Arriba GLACERA, la cantimplora que pensa en tu.\nAmb GLACERA, la teva aigua es mantindrà freda durant 24 hores, tant si és dins la motxilla com al sol del pati o a la platja. I a l'hivern, el teu brou o la teva infusió es mantindran calents fins a 12 hores.\nPer què GLACERA és diferent?\n- Té doble paret d'acer, resistent als cops.\n- No vessa ni una gota: el tap hermètic es tanca amb un sol clic.\n- És reutilitzable: adeu als envasos de plàstic d'un sol ús!\n- Es pot personalitzar amb adhesius i el teu nom.\n- La trobaràs en vuit colors brillants.\n«Des que tinc GLACERA, als partits de futbol sempre tinc aigua fresca», diu la Martina, de 12 anys.\nI ara, per celebrar-ne el llançament, si en compres dues, la segona et surt a meitat de preu! Només fins al 30 de novembre o fins a exhaurir existències.\nGLACERA. Frescor que t'acompanya.\nTrobaràs GLACERA a les millors botigues d'esports i a la nostra botiga en línia.",
