    "titol": "Previsió del temps a Osona",
    "tema": "Textos predictius: el temps",
    "text": "Previsió per al cap de setmana del 14 i el 15 de novembre.\nDissabte: el dia començarà amb boira densa a la Plana de Vic, sobretot a primera hora, que podria dificultar la visibilitat a les carreteres. A partir del migdia, la boira s'anirà aixecant i el cel quedarà poc ennuvolat. Les temperatures mínimes seran baixes, entre 0 i 2 graus, i no es descarta alguna gelada als fons de vall. Les màximes arribaran als 14 graus. El vent serà fluix.\nDiumenge: canvi de temps. Un front entrarà per l'oest i el cel s'anirà tapant al llarg del matí. A la tarda hi haurà pluges, que podrien ser moderades al Montseny i a les Guilleries i més febles a la plana. Per sobre dels 1.400 metres, la precipitació podria ser en forma de neu. Les temperatures baixaran i la màxima no passarà dels 10 graus. Bufarà vent del nord, que farà augmentar la sensació de fred.\nRecomanacions: si dissabte heu d'agafar el cotxe a primera hora, extremeu la precaució per la boira. Si teniu previst fer una excursió a la muntanya, aprofiteu el dissabte, perquè diumenge les condicions empitjoraran. I no us oblideu el paraigua!",
