    "titol": "Joaquima de Vedruna",
    "tema": "Biografies de dones rellevants",
    "text": "Joaquima de Vedruna va néixer a Barcelona el 16 d'abril de 1783. De petita ja mostrava una gran fe i, amb només dotze anys, va voler entrar en un convent, però no la van acceptar perquè era massa jove.\nAls setze anys es va casar amb Teodor de Mas, un advocat de Vic, i van tenir nou fills. L'any 1816 va morir el seu marit, i la Joaquima, que tenia poc més de trenta anys, es va quedar vídua amb els seus fills.\nUns anys més tard, va decidir complir el desig que tenia des de petita. Volia ajudar les persones que més ho necessitaven, sobretot els malalts i les nenes que no podien anar a escola, perquè en aquella època l'educació de les noies no es considerava tan important com la dels nois.\nL'any 1826, a Vic, va fundar amb un petit grup de dones la congregació de les Germanes Carmelites de la Caritat, que avui coneixem com a Vedruna. Aviat van obrir escoles i van atendre hospitals arreu de Catalunya.\nJoaquima va morir a Barcelona l'any 1854, víctima del còlera. L'any 1959 va ser declarada santa. Avui, les escoles Vedruna són presents a molts països del món.",
