    "titol": "Marie Curie",
    "tema": "Biografies de dones rellevants",
    "text": "Maria Skłodowska va néixer a Varsòvia (Polònia) l'any 1867. Era una alumna brillant, però en aquella època les dones no podien estudiar a la universitat del seu país. Per això, l'any 1891 es va traslladar a París, on va estudiar física i matemàtiques a la Sorbona. Tenia tan pocs diners que de vegades passava gana i estudiava amb l'abric posat perquè no podia escalfar l'habitació.\nA París va conèixer el científic Pierre Curie, amb qui es va casar. Junts van investigar uns materials que emetien una energia invisible, un fenomen que ella va anomenar radioactivitat. L'any 1898 van descobrir dos elements químics nous: el poloni, que van batejar així en honor de Polònia, i el radi.\nEl 1903, Marie Curie es va convertir en la primera dona que guanyava un premi Nobel, el de Física, que va compartir amb el seu marit i amb Henri Becquerel. El 1911 en va rebre un segon, aquesta vegada de Química. És l'única persona que ha guanyat el Nobel en dues ciències diferents.\nDurant la Primera Guerra Mundial va organitzar unitats mòbils de raigs X per atendre els soldats ferits. Va morir l'any 1934 per una malaltia causada per molts anys de treballar amb materials radioactius, quan encara no se'n coneixien bé els perills.",
