    "titol": "Mercè Rodoreda",
    "tema": "Biografies de dones rellevants",
    "text": "Mercè Rodoreda va néixer a Barcelona l'any 1908, al barri de Sant Gervasi. Va anar molt poc a escola, però a casa seva hi havia molts llibres, i el seu avi li va transmetre l'amor per la lectura i per les flors i els jardins, que després apareixerien sovint a les seves obres.\nDe jove va començar a escriure contes i novel·les, i l'any 1937 va guanyar un premi important amb la novel·la Aloma. Però el 1939, quan Franco va guanyar la Guerra Civil, va haver de marxar a l'exili, com molts altres escriptors catalans. Va viure a França i després a Ginebra, a Suïssa. Van ser anys durs, en què va treballar de cosidora i va passar moltes dificultats.\nLluny de casa va escriure la seva obra més coneguda: La plaça del Diamant, publicada el 1962. La novel·la explica la vida de la Natàlia, una noia del barri de Gràcia que viu la guerra i la postguerra. Està escrita amb un llenguatge tan senzill i proper que sembla que la protagonista ens parli a cau d'orella.\nEls últims anys de la seva vida, Rodoreda va tornar a Catalunya i es va instal·lar a Romanyà de la Selva, envoltada de natura. Va morir a Girona l'any 1983. Avui és considerada una de les escriptores més importants de la literatura catalana.",
