    "titol": "Lisboa, la ciutat dels set turons",
    "tema": "Blogs de viatges",
    "text": "Publicat el 22 de juliol\nHola, viatgers! Avui us escric des d'un mirador, amb vistes a les teulades taronja de Lisboa i al riu Tajo, que aquí és tan ample que sembla el mar.\nVam arribar fa tres dies i ja us puc dir una cosa: prepareu bones cames! Lisboa està construïda sobre set turons i tot són pujades i baixades. Per sort, hi ha el tramvia 28, un tramvia groc i antic que s'enfila pels carrers estrets del barri de l'Alfama. Anava tan atapeït que vam haver de fer tot el trajecte drets, però val la pena: a cada revolt apareix una vista nova.\nAhir vam anar al barri de Belém. Vam visitar la torre, que s'alça a la vora del riu, a prop d'on antigament salpaven els navegants cap a terres llunyanes. Després vam fer cua per tastar els famosos pastissets de nata, cruixents per fora i cremosos per dins. Me'n vaig menjar tres!\nEl que més m'ha agradat, però, són les façanes cobertes de rajoles pintades, que aquí anomenen azulejos. N'hi ha de blaves, de verdes, amb flors o amb dibuixos geomètrics.\nConsell del dia: porteu calçat còmode i una ampolla d'aigua. Demà marxem cap a Porto i us ho explicaré tot a la pròxima entrada.\nSi hi heu estat, deixeu-me un comentari!",
