    "titol": "Mòbils a l'escola? No, gràcies",
    "tema": "Text d'opinió: els mòbils",
    "text": "Aquest curs, a la nostra escola no es poden portar telèfons mòbils. Al principi, alguns companys es van queixar, però jo penso que és una bona decisió, i us explicaré per què.\nPrimer, perquè l'escola és un lloc per aprendre i per conviure. Si tinguéssim el mòbil a la butxaca, estaríem pendents de cada notificació i ens costaria molt més concentrar-nos. Fins i tot els adults reconeixen que, quan tenen el mòbil a prop, es distreuen sovint.\nSegon, perquè els patis serien diferents. He vist grups de joves asseguts l'un al costat de l'altre sense parlar-se, cadascun mirant la seva pantalla. Jo prefereixo córrer, jugar i xerrar amb els meus amics cara a cara.\nTercer, perquè a les xarxes de vegades es fan comentaris que fan mal, i a l'escola tots ens hem de sentir segurs.\nHi ha qui diu que el mòbil és útil per buscar informació o per avisar les famílies en cas d'emergència. És veritat, però per fer treballs ja tenim els ordinadors de l'aula, i si passa alguna cosa, l'escola truca de seguida a casa.\nNo vull dir que els mòbils siguin dolents. Són un invent fantàstic, però cada cosa té el seu moment i el seu lloc. I el lloc del mòbil no és la motxilla d'un alumne de primària.",
