    "titol": "Entrevista a una bombera",
    "tema": "L'entrevista: els oficis",
    "text": "L'Abril fa nou anys que és bombera i treballa en un parc de bombers d'una comarca de muntanya. Li hem preguntat com és la seva feina.\n—Abril, què fa un bomber quan no hi ha cap emergència?\n—Moltes coses! Revisem els camions i les mànegues, fem exercici cada dia per estar en forma i practiquem simulacres. També anem a les escoles a explicar com prevenir accidents.\n—Quina és la intervenció que recordes més?\n—Una nit d'hivern vam rescatar un excursionista que s'havia fet mal al turmell a la muntanya. Nevava i no hi vèiem gens. Quan el vam trobar, estava gelat però tranquil, perquè havia fet el que s'ha de fer: trucar al 112 i quedar-se quiet on era.\n—Has passat por alguna vegada?\n—És clar. La por no és dolenta: ens fa ser prudents. El que importa és saber controlar-la i confiar en l'equip.\n—Què hem de fer si veiem fum al bosc?\n—Allunyar-nos-en de seguida, cap al costat contrari d'on va el fum, i trucar al 112 per dir on som i què veiem.\n—Què li diries a un nen o una nena que vol ser bomber?\n—Que estudiï, que faci esport i que aprengui a treballar en equip. I a les nenes, que no s'ho pensin: cada vegada som més!",
