    "titol": "Elvira Montcau, la dibuixant d'ocells",
    "tema": "Biografia d'un personatge inventat",
    "text": "Elvira Montcau va néixer en una casa de pagès a la vora del Ter, en una època en què poques nenes podien estudiar. Des de ben petita s'enfilava a la figuera del pati amb un llapis i un tros de paper d'estrassa, i dibuixava els ocells que s'hi aturaven: pardals, caderneres, merles...\nAls dotze anys va haver de deixar l'escola per ajudar a casa. Però no va deixar mai de dibuixar. A les nits, a la llum d'un quinqué, omplia llibretes senceres d'esbossos d'ales, becs i plomes.\nUn estiu, un naturalista que estudiava els ocells de la comarca es va allotjar a la casa. Quan va veure els dibuixos de l'Elvira, va quedar meravellat i li va proposar que il·lustrés el llibre que preparava. Aquell llibre, amb més de cent làmines pintades a l'aquarel·la, la va fer coneguda.\nDurant la resta de la seva vida, l'Elvira va il·lustrar guies de natura i contes per a infants. Deia que, per dibuixar bé un ocell, primer calia aprendre a mirar-lo amb paciència, sense fer soroll, de vegades durant hores.\nJa gran, va regalar totes les seves llibretes a l'escola del poble perquè els nens i nenes hi poguessin aprendre. Avui, la biblioteca de l'escola porta el seu nom.",
