    "tema": "La notícia: la robòtica",
    "text": "Vic, 8 de maig. Una trentena d'equips d'alumnes de cinquè i sisè de diverses escoles d'Osona van participar dissabte en una trobada de robòtica escolar celebrada en un pavelló de Vic. La prova principal consistia a programar un petit robot perquè travessés un circuit ple d'obstacles i transportés tres cubs de colors fins a una zona marcada.\nCada equip, format per quatre alumnes, havia passat dos mesos dissenyant i programant el seu robot. Els participants van haver de superar tres rondes, i a cadascuna disposaven de dos minuts i mig per completar el recorregut.\nL'equip guanyador, d'una escola de Manlleu, va aconseguir portar els tres cubs a la zona marcada en només un minut i quaranta segons. «Al principi el robot girava massa i xocava contra la paret, però vam ajustar els sensors i al final ho vam aconseguir», explicava, emocionada, una de les integrants.\nA més de la prova del circuit, el jurat va valorar la presentació oral de cada projecte i la capacitat dels equips per treballar junts i resoldre problemes.\nEls organitzadors van destacar que el més important no era guanyar, sinó aprendre a provar, equivocar-se i tornar-ho a intentar. La trobada es repetirà el curs vinent.",
