    "titol": "Quanta pluja ha caigut?",
    "tema": "Gràfic descrit en text: la pluja",
    "text": "Des de fa tres cursos, la nostra escola té una petita estació meteorològica al terrat. Cada dia, a les nou del matí, un alumne de sisè mira el pluviòmetre i apunta quanta pluja ha caigut. Amb les dades d'aquest any, de gener a juny, hem fet un gràfic de barres. Us l'expliquem.\nA l'eix horitzontal hi ha els sis mesos, i a l'eix vertical, la quantitat de pluja en litres per metre quadrat (l/m²).\nAl gener van caure 20 l/m², i al febrer, el mes més sec, només 15. Al març la barra puja fins a 35, i a l'abril arriba a 60. El maig és el mes més plujós, amb 75 l/m²: la seva barra és cinc vegades més alta que la del febrer. Finalment, al juny la pluja baixa fins a 40 l/m².\nEn total, en aquests sis mesos han caigut 245 litres per metre quadrat.\nQuan vam comparar el gràfic amb el de l'any passat, vam veure que la forma era semblant: poca pluja a l'hivern i molta més a la primavera. Però aquest any el maig ha estat més plujós. Els mestres ens van recordar que, per saber com és el clima d'un lloc, no n'hi ha prou amb un any: cal recollir dades durant molt de temps.",
