    "titol": "Recepta per fer un amic",
    "tema": "La poesia: l'amistat",
    "text": "Agafa un grapat de paraules\nque siguin dolces i sinceres,\ni barreja-les amb rialles\ni alguna broma de les teves.\n\nAfegeix-hi una tassa de temps,\nque l'amistat no té pressa;\nescolta-ho tot amb paciència,\nfins i tot el que no t'interessa.\n\nSi algun dia es crema la massa\nper una baralla o un mal gest,\nno la llencis: amb un «ho sento»\nsovint se'n salva tota la resta.\n\nDeixa-la reposar a l'escalfor\ndels jocs al pati i dels secrets,\ni comparteix-ho tot a mitges:\nl'entrepà, els contes i els patinets.\n\nNo cal forn ni cal batedora,\nni cap ingredient car;\nnomés dues mans obertes\ni un cor que sàpiga esperar.\n\nI quan la recepta et surti,\nno la desis en un calaix:\nregala-la a qui la vulgui,\nque els amics no sobren mai.",
