 "frases": {
  "2": [
   "El gat dorm al sofà.",
   "La Marta menja una poma.",
   "Els nens canten una cançó.",
   "La mestra llegeix un conte.",
   "El gos té gana.",
   "Jo bec un got de llet.",
   "La lluna és molt bonica.",
   "El pare cuina macarrons.",
   "Les flors són de colors.",
   "El tren arriba a l'estació.",
   "Els ocells volen pel cel.",
   "La nena pinta un dibuix.",
   "El peix neda a l'aigua.",
   "El cotxe és de color vermell.",
   "Tinc un gatet molt petit.",
   "La Laia salta a corda.",
   "En Pau escriu una carta.",
   "El sol escalfa la terra.",
   "La Júlia té els ulls blaus.",
   "El nen beu aigua fresca.",
   "Els ànecs neden al llac.",
   "La sopa està molt calenta.",
   "Els conills mengen pastanagues.",
   "La papallona té ales grogues.",
   "La vaca menja herba.",
   "El nen porta una gorra.",
   "La Clara té un gat negre.",
   "Els peixos neden al riu.",
   "La mare compra pa.",
   "Les gallines ponen ous.",
   "En Pol menja una pera.",
   "La nena té els cabells llargs.",
   "El gat beu llet.",
   "El llop viu al bosc.",
   "La Laia menja un gelat de maduixa.",
   "Avui fa molt de sol.",
   "Jo tinc una bicicleta vermella.",
   "L'avi llegeix el diari.",
   "La granota salta al bassal.",
   "El forner fa pa.",
   "Els ocells canten als arbres.",
   "La Marta té tres germans."
  ],
  "3": [
   "El gos del veí borda tota la nit.",
   "Els nens de tercer canten molt bé.",
   "La mestra explica un conte molt divertit.",
   "Les orenetes fan el niu sota la teulada.",
   "En Marc s'ha menjat tot l'entrepà.",
   "La Núria porta una motxilla de color blau.",
   "Els bombers apaguen un incendi molt gran.",
   "El cuiner prepara una sopa molt calenta.",
   "Els astronautes viatgen dins d'una nau espacial.",
   "La papallona vola damunt de les flors.",
   "Les vaques mengen herba al prat.",
   "El pagès recull les pomes de l'arbre.",
   "La biblioteca de l'escola té molts llibres.",
   "El ratolí s'amaga dins d'un forat.",
   "Els pingüins viuen en llocs molt freds.",
   "El pallasso fa riure tots els nens.",
   "La Clara dibuixa un castell amb colors.",
   "Els alumnes escolten la mestra amb atenció.",
   "La girafa té el coll molt llarg.",
   "Els esquirols guarden avellanes per a l'hivern.",
   "La tortuga camina molt a poc a poc.",
   "Les estrelles brillen dalt del cel.",
   "La cuinera talla les verdures amb un ganivet.",
   "El bomber puja per una escala molt llarga.",
   "Els esquiadors baixen per la pista vermella.",
   "El mussol té uns ulls molt grossos.",
   "La Paula s'ha trencat el braç esquerre.",
   "La girafa menja les fulles dels arbres.",
   "En Roc s'ha posat les botes d'aigua.",
   "Els cargols surten quan plou.",
   "El porter ha aturat un penal molt difícil.",
   "L'esquirol s'enfila a dalt de l'arbre.",
   "En Pau i la Laia fan un trencaclosques.",
   "La Mireia ha guanyat la cursa de natació."
  ],
  "4": [
   "Els alumnes de quart van d'excursió al museu de la ciència.",
   "La bibliotecària ens va recomanar un llibre d'aventures molt emocionant.",
   "Els pagesos de la comarca cultiven unes pomes boníssimes.",
   "La Mariona va trobar una petxina blanca a la platja.",
   "El científic observa les cèl·lules amb un microscopi molt potent.",
   "Les cigonyes construeixen els nius a dalt del campanar.",
   "Els bombers van rescatar un gatet que estava atrapat.",
   "El riu Mèder passa per la ciutat de Vic.",
   "Els turistes visiten el temple romà de Vic.",
   "La professora de música ens ensenya a tocar la flauta.",
   "El cuiner del restaurant prepara un arròs boníssim.",
   "La neu cobreix els cims de les muntanyes del Pirineu.",
   "El vent de tramuntana va fer caure les fulles dels arbres.",
   "Els nens van construir una cabana amb branques seques.",
   "La lluna plena il·lumina el camí dels excursionistes cansats.",
   "Les abelles fabriquen la mel dins del rusc.",
   "El mercat de Vic se celebra a la plaça Major.",
   "Els dofins són animals molt intel·ligents que viuen al mar.",
   "El tren de les nou ha arribat amb mitja hora de retard.",
   "Els astrònoms estudien els planetes amb grans telescopis.",
   "El jardiner rega les plantes amb una mànega verda.",
   "En Martí s'ha trencat el braç jugant a futbol.",
   "La biblioteca municipal obre les portes a les quatre de la tarda.",
   "La mestra ha llegit un conte que parla d'un drac verd.",
   "La Júlia ha escrit una carta als Reis d'Orient.",
   "Els bombers han rescatat un gat que s'havia enfilat a un arbre.",
   "La Marina s'ha comprat un paraigua de color groc.",
   "Aquesta tarda hem vist un arc de Sant Martí enorme.",
   "La Carla ha après a nedar a la piscina municipal.",
   "Els castellers han aixecat un castell de nou pisos."
  ]
 },
